/* @autogenerated */
import { Component, inject } from '@angular/core';
import { ResourceServer } from 'app/features/access/resource-server/model/resource-server.model';
import { ResourceServerRepository } from 'app/features/access/resource-server/repository/resource-server-repository.service';
import { ConfirmSelectionAction } from 'app/shared/toolkit/action/confirm-selection-action';

@Component({ selector: 'resource-server-view-disable-selection-action', standalone: false, template: '' })
export class ResourceServerViewDisableSelectionActionComponent extends ConfirmSelectionAction<ResourceServer> {
  readonly name = 'disableSelection';
  protected readonly scope = 'access/resource-server';
  protected readonly repository = inject(ResourceServerRepository);

  protected override appliesTo(items: ResourceServer[]) {
    return items.every((item) => item.enabled !== false);
  }

  protected runSelection(items: ResourceServer[]) {
    return this.repository.disableSelection({ uids: items.map((item) => item.uid) });
  }
}
